//! Embeds `assets/chernobyl.ico` (generated by scripts/brand/make-logo-assets.mjs
//! from the owner's logo) as the exe icon that Explorer, the taskbar and
//! shortcuts show. std-only like the crate (ADR-010): the `.res` file is
//! written here byte by byte and handed to the MSVC linker, which takes `.res`
//! inputs directly, so no resource compiler is needed.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-changed=assets/chernobyl.ico");
    if env::var("CARGO_CFG_TARGET_ENV").as_deref() != Ok("msvc") {
        // other linkers need their own resource tooling; the icon is cosmetic
        return;
    }
    let ico = fs::read("assets/chernobyl.ico").expect("read assets/chernobyl.ico");
    let res = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("chernobyl.res");
    fs::write(&res, res_from_ico(&ico)).expect("write chernobyl.res");
    println!("cargo:rustc-link-arg-bins={}", res.display());
}

const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;
const LANG_EN_US: u16 = 0x0409;

/// One RT_ICON per image (ordinals 1..n) plus the RT_GROUP_ICON directory
/// (ordinal 1) that points at them, after the empty entry a `.res` starts with.
fn res_from_ico(ico: &[u8]) -> Vec<u8> {
    let u16_at = |i: usize| u16::from_le_bytes([ico[i], ico[i + 1]]);
    let u32_at = |i: usize| u32::from_le_bytes([ico[i], ico[i + 1], ico[i + 2], ico[i + 3]]);
    assert!(ico.len() >= 6 && u16_at(2) == 1, "not an .ico file");
    let count = u16_at(4) as usize;

    let mut out = Vec::new();
    entry(&mut out, 0, 0, 0, &[]);
    let mut group = Vec::new();
    group.extend_from_slice(&0u16.to_le_bytes());
    group.extend_from_slice(&1u16.to_le_bytes());
    group.extend_from_slice(&(count as u16).to_le_bytes());
    for n in 0..count {
        let e = 6 + n * 16;
        let (len, offset) = (u32_at(e + 8) as usize, u32_at(e + 12) as usize);
        let id = (n + 1) as u16;
        entry(&mut out, RT_ICON, id, 0x1010, &ico[offset..offset + len]);
        // GRPICONDIRENTRY: the ICONDIRENTRY's first 12 bytes + the resource id
        group.extend_from_slice(&ico[e..e + 12]);
        group.extend_from_slice(&id.to_le_bytes());
    }
    entry(&mut out, RT_GROUP_ICON, 1, 0x1030, &group);
    out
}

/// A `.res` entry with an ordinal type and name: a 32-byte header, then the
/// data padded to a DWORD boundary.
fn entry(out: &mut Vec<u8>, kind: u16, name: u16, flags: u16, data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out.extend_from_slice(&32u32.to_le_bytes());
    for v in [0xFFFF, kind, 0xFFFF, name] {
        out.extend_from_slice(&u16::to_le_bytes(v));
    }
    out.extend_from_slice(&0u32.to_le_bytes()); // DataVersion
    out.extend_from_slice(&flags.to_le_bytes());
    let lang = if kind == 0 { 0 } else { LANG_EN_US };
    out.extend_from_slice(&lang.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // Version
    out.extend_from_slice(&0u32.to_le_bytes()); // Characteristics
    out.extend_from_slice(data);
    while !out.len().is_multiple_of(4) {
        out.push(0);
    }
}
